css:
#tongsci1-3-3-2-1-osmosis .os-body { grid-template-columns: 1120px minmax(0, 1fr); }
#tongsci1-3-3-2-1-osmosis .os-stage { position: relative; border: 2px solid var(--ink); border-radius: 12px; overflow: hidden; background: #f5f2ea; }
#tongsci1-3-3-2-1-osmosis .os-stage canvas { touch-action: none; cursor: grab; user-select: none; -webkit-user-select: none; }
#tongsci1-3-3-2-1-osmosis .os-stage .now-chip { top: auto; bottom: 10px; left: 14px; font-size: 18px; padding: 6px 14px; }
#tongsci1-3-3-2-1-osmosis .os-tray { gap: 8px; }
#tongsci1-3-3-2-1-osmosis .os-tray .tray-item { font-size: 17px; padding: 9px 12px; cursor: pointer; }
#tongsci1-3-3-2-1-osmosis .os-panel { gap: 12px; }
#tongsci1-3-3-2-1-osmosis .os-out { margin: 0; font-size: 20px; line-height: 1.5; background: #fffbe6; border: 2px solid var(--accent); border-radius: 12px; padding: 10px 14px; min-height: 6.2em; flex: none; }
#tongsci1-3-3-2-1-osmosis .os-out b { color: var(--accent); }
#tongsci1-3-3-2-1-osmosis .os-tab { width: 100%; border-collapse: collapse; table-layout: fixed; font: 600 17px/1.3 var(--f-body); flex: none; background: var(--paper-2); border: 2px solid var(--ink); }
#tongsci1-3-3-2-1-osmosis .os-tab thead th { font: 800 17px/1.2 var(--f-body); background: color-mix(in srgb, var(--accent) 10%, var(--paper-2)); border: 1.5px solid var(--ink-3); padding: 5px 4px; }
#tongsci1-3-3-2-1-osmosis .os-tab thead th.an { color: #a3302b; }
#tongsci1-3-3-2-1-osmosis .os-tab thead th.pl { color: #6e2a66; }
#tongsci1-3-3-2-1-osmosis .os-tab small { font-size: 14px; color: var(--ink-3); font-weight: 600; }
#tongsci1-3-3-2-1-osmosis .os-tab tbody th { font: 800 17px/1.2 var(--f-body); border: 1.5px solid var(--rule, #c9ccd3); background: color-mix(in srgb, var(--ink) 4%, var(--paper-2)); padding: 4px; }
#tongsci1-3-3-2-1-osmosis .os-tab td { border: 1.5px solid var(--rule, #c9ccd3); padding: 4px 6px; height: 44px; text-align: center; transition: background .3s; }
#tongsci1-3-3-2-1-osmosis .os-tab td b { color: var(--ink); }
#tongsci1-3-3-2-1-osmosis .os-tab td.pick { background: color-mix(in srgb, var(--hl) 60%, #fff); box-shadow: inset 0 0 0 3px var(--ink); }
#tongsci1-3-3-2-1-osmosis .os-def { margin: 0; display: grid; gap: 8px; flex: none; }
#tongsci1-3-3-2-1-osmosis .os-def div { border-left: 6px solid #2a7fc0; background: color-mix(in srgb, #2a7fc0 9%, var(--paper-2)); border-radius: 0 10px 10px 0; padding: 6px 14px; }
#tongsci1-3-3-2-1-osmosis .os-def dt { font: 800 19px var(--f-body); color: #1d5f94; }
#tongsci1-3-3-2-1-osmosis .os-def dd { margin: 2px 0 0; font-size: 17px; line-height: 1.45; }
section#tongsci1-3-3-2-1-osmosis.ex.u-done .os-def { display: none; }

